"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[60681],{46057:e=>{e.exports=JSON.parse('{"product":"Connect","entries":[{"id":"2026-08-07-viber-message-templates","date":"2026-08-07","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber message templates","excerpt":"You can now create and manage Viber message templates \u2014 pre-approved message formats for transactional messages and OTPs, with dynamic {{parameter}} placeholders substituted at send time. Creating templates requires an admin role on the account.","hasArticle":true},{"id":"2026-08-05-rcs-attribution-corrected","date":"2026-08-05","products":["Connect"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS attribution corrected","excerpt":"The RCS guide previously described Rich Communication Services as \\"a protocol developed by Google.\\" That was inaccurate, and it is now corrected.","hasArticle":true},{"id":"2026-08-04-templateid-in-direct-send-delivery-receipts","date":"2026-08-04","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"templateId in Direct Send delivery receipts","excerpt":"WhatsApp delivery receipts now include a templateId field for messages sent via the WhatsApp Direct Send API, so you can correlate a receipt back to the exact template that was delivered.","hasArticle":true},{"id":"2026-08-03-line-channel-documentation","date":"2026-08-03","products":["Connect"],"product":"Connect","channel":"LINE","changeType":"Added","title":"LINE channel documentation","excerpt":"The full LINE channel documentation is now published. LINE is the most popular chat app in Japan, Thailand, and Taiwan, and it reaches users through the same 8x8 Messaging Apps API and webhook envelope you already use for SMS, WhatsApp, Viber, and RCS.","hasArticle":true},{"id":"2026-07-28-verification-api-templatekey-parameter","date":"2026-07-28","products":["Connect","APIs"],"product":"Connect","channel":"Verification","changeType":"Changed","title":"Verification API templateKey parameter","excerpt":"The Verification API request now accepts a templateKey parameter, letting you select a pre-saved message template by its key instead of supplying the message content inline. The example values used across the Verification API documentation have also been standardised.","hasArticle":true},{"id":"2026-07-28-whatsapp-automatic-events-webhook","date":"2026-07-28","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Automatic Events webhook","excerpt":"You can now receive WhatsApp Automatic Events webhooks \u2014 notifications sent when Meta detects a qualifying conversion event (a purchase or a lead) inside a WhatsApp thread that originated from a Click-to-WhatsApp ad. 8x8 forwards these detected events to your endpoint so you can feed conversion data into your own analy\u2026","hasArticle":true},{"id":"2026-07-21-business-scoped-user-ids-bsuid","date":"2026-07-21","products":["Connect","APIs"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"Business-Scoped User IDs (BSUID)","excerpt":"WhatsApp is rolling out optional usernames, which let people message a business without handing over their phone number. So that those users stay reachable, Meta gives every WhatsApp user a persistent Business-Scoped User ID (BSUID). 8x8 now surfaces the BSUID as user.channelUserId throughout the WhatsApp over 8x8 API.\u2026","hasArticle":true},{"id":"2026-07-21-outbound-context-on-outbound-api-v9","date":"2026-07-21","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Changed","title":"Outbound context on Outbound API v9","excerpt":"Outbound Messaging Apps delivery receipts on version 9 now carry additional context about the message they refer to. A new outboundContent object gives you a structured, channel-normalized copy of the WhatsApp message that was delivered, so you can reconcile a delivery receipt with the exact content sent without keepin\u2026","hasArticle":true},{"id":"2026-07-16-whatsapp-request-call-info","date":"2026-07-16","products":["Connect","APIs"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Request Call Info","excerpt":"You can now check a customer\'s WhatsApp call permission status before you place a business-initiated call. Meta requires customers to explicitly grant permission before a business can call them on WhatsApp, and the new Get Call Permission Status endpoint tells you whether that permission is in place, whether you are cu\u2026","hasArticle":true},{"id":"2026-07-07-chat-apps-inbound-and-outbound-messaging","date":"2026-07-07","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Added","title":"Chat Apps inbound and outbound messaging","excerpt":"You can now follow end-to-end how-to documentation for sending and receiving Chat Apps messages on the 8x8 platform. The Chat Apps API lets you reach customers across supported channels \u2014 WhatsApp, Viber, RCS, LINE, and others \u2014 through a single message API, and receive their replies and delivery updates on the webhook\u2026","hasArticle":true}]}')}}]);